<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Receipt {{ $order->reference_number }}</title><style>
body{font-family:Arial,sans-serif;color:#111;background:#f3f4f6;margin:0}.receipt{width:80mm;max-width:calc(100% - 24px);margin:24px auto;background:white;padding:5mm;box-sizing:border-box;font-size:12px}.center{text-align:center}.row{display:flex;justify-content:space-between;gap:8px;margin:6px 0}.rule{border:0;border-top:1px dashed #555;margin:12px 0}.strong{font-weight:700}.actions{text-align:center;margin:18px}.actions button{padding:10px 16px;background:#b91c1c;color:white;border:0;border-radius:8px;font-weight:bold;cursor:pointer}@media print{body{background:white}.receipt{margin:0;max-width:none;width:80mm;padding:3mm}.actions{display:none}@page{size:80mm auto;margin:0}}
</style></head><body><main class="receipt"><header class="center"><h2 style="margin:0 0 5px">PASSENGER SEAT</h2><p style="margin:0">Restaurant · Official Order Receipt</p><p>SM City San Mateo, Rizal</p></header><hr class="rule"><div class="row"><span>Reference</span><span class="strong">{{ $order->reference_number }}</span></div><div class="row"><span>Date</span><span>{{ $order->created_at->format('Y-m-d H:i') }}</span></div><div class="row"><span>Service</span><span>{{ $order->type === 'dine_in' ? 'Dine-in / Table '.$order->table_number : 'Take-out' }}</span></div><hr class="rule">@foreach ($order->items as $item)<div class="row"><span>{{ $item->quantity }} × {{ $item->item_name }}</span><span>₱{{ number_format((float) $item->price * $item->quantity, 2) }}</span></div>@endforeach<hr class="rule"><div class="row strong"><span>TOTAL</span><span>₱{{ number_format((float) $order->total_amount, 2) }}</span></div><div class="row"><span>Payment</span><span>{{ ucfirst($order->payment_status) }}</span></div>@if ($order->payment_method)<div class="row"><span>Method</span><span>{{ strtoupper($order->payment_method) }}</span></div>@endif@if ($order->paid_at)<div class="row"><span>Paid at</span><span>{{ $order->paid_at->format('Y-m-d H:i') }}</span></div>@endif<hr class="rule"><p class="center">Thank you for dining with us!</p><p class="center">Please keep this receipt for your records.</p></main><div class="actions"><button onclick="window.print()">Print receipt</button> <button onclick="window.history.back()">Back</button></div></body></html>
